import React, { useEffect, useState } from "react";
import { supabase } from "../supabaseClient";
import SlotCard from "../components/SlotCard";

const AdminDashboard = () => {
  const [slots, setSlots] = useState([]);

  useEffect(() => {
    fetchSlots();
    const interval = setInterval(fetchSlots, 2000);
    return () => clearInterval(interval);
  }, []);

  async function fetchSlots() {
    const { data, error } = await supabase
      .from("parking_slots")
      .select("*")
      .order("slot", { ascending: true });
    if (error) console.log(error);
    else setSlots(data);
  }

  const totalSlots = slots.length;
  const occupied = slots.filter(s => s.status === "occupied").length;
  const vacant = totalSlots - occupied;

  return (
    <div style={{ padding: "20px" }}>
      <h1>🚗 Admin Dashboard</h1>
      <div style={{ display: "flex", gap: "20px", margin: "20px 0" }}>
        <div>Total Slots: {totalSlots}</div>
        <div style={{ color: "#ff4d4d" }}>Occupied: {occupied}</div>
        <div style={{ color: "#4CAF50" }}>Vacant: {vacant}</div>
      </div>
      <div style={{ display: "flex", flexWrap: "wrap" }}>
        {slots.map(slot => <SlotCard key={slot.id} slot={slot} />)}
      </div>
    </div>
  );
};

export default AdminDashboard;
